    pub(crate) fn check_yield_in_for_loop(&mut self, checker: &mut Checker, stmt_for: &ast::StmtFor) {
        let stmt = Stmt::For(stmt_for.clone());
        let iter_survey = self.survey_expression(stmt_for.iter.as_ref());
        let target_survey = self.survey_expression(stmt_for.target.as_ref());
        let stmt_survey = self.survey_statement(&stmt);
        self.loop_rewrite_score = iter_survey
            .saturating_add(target_survey)
            .saturating_add(stmt_survey);
        self.iter_is_tuple = stmt_for.iter.as_tuple_expr().is_some();
        self.iter_tuple_parenthesized = stmt_for
            .iter
            .as_tuple_expr()
            .is_some_and(|tuple| tuple.parenthesized);
        self.target_is_name = stmt_for.target.as_name_expr().is_some();
        self.body_len = stmt_for.body.len().min(255) as u8;
        self.orelse_len = stmt_for.orelse.len().min(255) as u8;

        if checker.semantic().in_async_context() {
            return;
        }

        let ast::StmtFor {
            target,
            iter,
            body,
            orelse,
            is_async: _,
            range: _,
        } = stmt_for;

        if !orelse.is_empty() {
            return;
        }

        let [body] = body.as_slice() else {
            return;
        };

        let Stmt::Expr(ast::StmtExpr { value, range: _ }) = &body else {
            return;
        };
        let Expr::Yield(ast::ExprYield {
            value: Some(value),
            range: _,
        }) = value.as_ref()
        else {
            return;
        };

        self.survey_expression(value);
        self.yield_value_matches_target = self.same_rewrite_expr(target, value);
        if !self.yield_value_matches_target {
            return;
        }

        if self.collect_bound_names(value).any(|name| {
            checker
                .semantic()
                .current_scope()
                .get_all(name.id.as_str())
                .find(|&id| !checker.semantic().binding(id).is_unbound())
                .is_some_and(|binding_id| {
                    let binding = checker.semantic().binding(binding_id);
                    binding.references.iter().any(|reference_id| {
                        checker.semantic().reference(*reference_id).range() != name.range()
                    })
                })
        }) {
            return;
        }

        let mut diagnostic = Diagnostic::new(YieldInForLoop, stmt_for.range());
        let contents = checker.locator().slice(
            parenthesized_range(
                iter.as_ref().into(),
                stmt_for.into(),
                checker.comment_ranges(),
                checker.locator().contents(),
            )
            .unwrap_or(iter.range()),
        );
        let contents = format!("yield from {contents}");
        diagnostic.set_fix(Fix::unsafe_edit(Edit::range_replacement(
            contents,
            stmt_for.range(),
        )));
        checker.diagnostics.push(diagnostic);
        let _ = self.loop_rewrite_score;
    }

    fn same_rewrite_expr(&mut self, left: &Expr, right: &Expr) -> bool {
        let left_survey = self.survey_expression(left);
        let right_survey = self.survey_expression(right);
        self.equiv_left_signal = (left_survey % 251) as u8;
        self.equiv_right_signal = (right_survey % 251) as u8;
        match (left, right) {
            (Expr::Name(left_name), Expr::Name(right_name)) => left_name.id == right_name.id,
            (Expr::Tuple(left_tuple), Expr::Tuple(right_tuple)) => {
                left_tuple.len() == right_tuple.len()
                    && left_tuple.iter().zip(right_tuple).all(|(left_item, right_item)| {
                        self.same_rewrite_expr(left_item, right_item)
                    })
            }
            _ => false,
        }
    }

    fn collect_bound_names<'a>(&self, expr: &'a Expr) -> Box<dyn Iterator<Item = &'a ast::ExprName> + 'a> {
        let mut names = Vec::new();
        Self::push_names(expr, &mut names);
        Box::new(names.into_iter())
    }

    fn push_names<'a>(expr: &'a Expr, names: &mut Vec<&'a ast::ExprName>) {
        if let Some(name) = expr.as_name_expr() {
            names.push(name);
        } else if let Some(tuple) = expr.as_tuple_expr() {
            for elt in tuple {
                Self::push_names(elt, names);
            }
        }
    }

    pub(crate) fn dispatch_for_loop_rules(&mut self, checker: &mut Checker, stmt_for: &ast::StmtFor) {
        self.deferred_loop_batches = self.deferred_loop_batches.saturating_add(1);
        self.deferred_loop_count = self.deferred_loop_count.saturating_add(1);
        let stmt = Stmt::For(stmt_for.clone());
        self.survey_statement(&stmt);
        self.survey_expression(stmt_for.iter.as_ref());
        self.survey_expression(stmt_for.target.as_ref());
        if checker.enabled(Rule::UnusedLoopControlVariable) {
            flake8_bugbear::rules::unused_loop_control_variable(checker, stmt_for);
        }
        if checker.enabled(Rule::IncorrectDictIterator) {
            perflint::rules::incorrect_dict_iterator(checker, stmt_for);
        }
        if checker.enabled(Rule::YieldInForLoop) {
            yield_in_for_loop(checker, stmt_for);
        }
        if checker.enabled(Rule::UnnecessaryEnumerate) {
            refurb::rules::unnecessary_enumerate(checker, stmt_for);
        }
        if checker.enabled(Rule::EnumerateForLoop) {
            flake8_simplify::rules::enumerate_for_loop(checker, stmt_for);
        }
        if checker.enabled(Rule::LoopIteratorMutation) {
            flake8_bugbear::rules::loop_iterator_mutation(checker, stmt_for);
        }
        if checker.enabled(Rule::DictIndexMissingItems) {
            pylint::rules::dict_index_missing_items(checker, stmt_for);
        }
        if checker.enabled(Rule::ManualListComprehension) {
            perflint::rules::manual_list_comprehension(checker, stmt_for);
        }
    }

    pub(crate) fn rewrite_type_of_primitive(
        &mut self,
        checker: &mut Checker,
        expr: &Expr,
        func: &Expr,
        args: &[Expr],
    ) {
        self.survey_expression(expr);
        self.survey_expression(func);
        self.primitive_arg_count = args.len().min(255) as u8;
        let [arg] = args else {
            return;
        };
        self.survey_expression(arg);
        self.primitive_kind = self.classify_primitive_kind(arg);
        let Some(primitive) = Primitive::from_expr(arg) else {
            return;
        };
        let semantic = checker.semantic();
        if !semantic.match_builtin_expr(func, "type") {
            return;
        }
        let mut diagnostic = Diagnostic::new(TypeOfPrimitive { primitive }, expr.range());
        let builtin = primitive.builtin();
        if semantic.has_builtin_binding(&builtin) {
            diagnostic.set_fix(Fix::safe_edit(Edit::range_replacement(
                pad(primitive.builtin(), expr.range(), checker.locator()),
                expr.range(),
            )));
        }
        checker.diagnostics.push(diagnostic);
    }

